const validEmail = (s) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(s || '').trim());
const esc = (s) => String(s || '').replace(/[<>]/g, '');
const norm = (lead) => ({
  name: esc(lead.name).slice(0, 80),
  company: esc(lead.company).slice(0, 120),
  email: String(lead.email || '').trim().toLowerCase().slice(0, 254),
  service: esc(lead.service).slice(0, 120),
  urgency_days: Number.isFinite(Number(lead.urgency_days)) ? Math.max(0, Number(lead.urgency_days)) : 999,
  estimated_budget_eur: Number.isFinite(Number(lead.estimated_budget_eur)) ? Math.max(0, Number(lead.estimated_budget_eur)) : 0,
  message: esc(lead.message).slice(0, 1500)
});
return $input.all().map((item, idx) => {
  const lead = norm(item.json);
  const issues = [];
  if (!validEmail(lead.email)) issues.push('invalid_email');
  if (!lead.service) issues.push('missing_service');
  // This is deterministic priority scoring, NOT an AI model or an audited sales outcome prediction.
  let score = 0;
  score += lead.urgency_days <= 1 ? 35 : lead.urgency_days <= 3 ? 25 : lead.urgency_days <= 7 ? 15 : 5;
  score += lead.estimated_budget_eur >= 5000 ? 25 : lead.estimated_budget_eur >= 1000 ? 15 : 0;
  score += lead.service ? 20 : 0;
  score += validEmail(lead.email) ? 10 : 0;
  score += lead.message.length >= 40 ? 10 : 0;
  const priority = issues.length ? 'REVIEW' : score >= 70 ? 'HOT' : score >= 40 ? 'WARM' : 'LOW';
  const recipient = lead.name || 'there';
  const draft = `Hi ${recipient},\\n\\nThank you for contacting us about ${lead.service || 'your request'}. We have received your enquiry and will review the details. A team member will follow up to clarify the scope and next steps.\\n\\nBest regards,\\nThe team`;
  return { json: { ...lead, score, priority, issues, draft_reply: draft.replaceAll(String.fromCharCode(92) + "n", String.fromCharCode(10)), outbound_sent: false, needs_human_approval: true, expected_priority: item.json.expected_priority || null }, pairedItem: { item: idx } };
});

const items = $input.all();
const results = items.map(i => ({ name: i.json.name, expected: i.json.expected_priority, actual: i.json.priority, pass: i.json.expected_priority === i.json.priority, outbound_sent: i.json.outbound_sent }));
const all_pass = results.every(x => x.pass && x.outbound_sent === false);
return [{ json: { all_pass, passed: results.filter(r=>r.pass).length, total: results.length, results, note: 'Synthetic educational test cases only. Verify in your own n8n instance; this is not a production-ready lead scoring system.' } }];
